-- 115_ficha_producao_saude_estoque.sql
-- Ficha do Gerenciamento de Produção: Saúde do Estoque classificada no servidor (S1 do plano). Aditiva e idempotente.

UPDATE mapa_modules SET
    detail = jsonb_set(detail, '{attention}', COALESCE(detail->'attention', '[]'::jsonb) || to_jsonb('Saúde do Estoque de dois lados (só leitura, GET /api/producao/saude-estoque, ação classificar_saude_estoque): cada produto acabado e kit é classificado no servidor em Ruptura (sem estoque físico ou pedido em aberto acima do estoque, e com venda), Baixo (a Demanda de Produção marca abrir ordem ou produzir urgente), Adequado, Excesso (estoque da Demanda acima de 2× o ideal; com ideal zero, qualquer estoque) ou Sem giro (180 dias ou mais sem venda; quem nunca vendeu conta desde a última produção, e sem produção também é sem giro). Sem giro vence as demais; lançamento, encomenda e terceirizado aparecem como Especial, com selo, fora de ruptura, baixo e sem giro. Usa o mesmo estoque, média de vendas, ideal e status da Demanda (calculo::listar_produtos), nada recalculado à parte. Vendas de 3 e 12 meses vêm de historico_faturamento (12 meses fechados por mês do calendário); última venda = pedido mais recente não cancelado em sales_orders; última produção = última entrada de produto em stock_movements. Base, coloração, apoio e inativos ficam fora. Código em modules/producao/saude_estoque.rs. Decisões do Edson (2026-11-10): excesso acima de 2× o ideal, sem giro com 180 dias, primeira entrega só produtos acabados e kits'::text)),
    updated_at = NOW()
WHERE module_key = 'producao'
  AND NOT (COALESCE(detail->'attention', '[]'::jsonb) @> to_jsonb('Saúde do Estoque de dois lados (só leitura, GET /api/producao/saude-estoque, ação classificar_saude_estoque): cada produto acabado e kit é classificado no servidor em Ruptura (sem estoque físico ou pedido em aberto acima do estoque, e com venda), Baixo (a Demanda de Produção marca abrir ordem ou produzir urgente), Adequado, Excesso (estoque da Demanda acima de 2× o ideal; com ideal zero, qualquer estoque) ou Sem giro (180 dias ou mais sem venda; quem nunca vendeu conta desde a última produção, e sem produção também é sem giro). Sem giro vence as demais; lançamento, encomenda e terceirizado aparecem como Especial, com selo, fora de ruptura, baixo e sem giro. Usa o mesmo estoque, média de vendas, ideal e status da Demanda (calculo::listar_produtos), nada recalculado à parte. Vendas de 3 e 12 meses vêm de historico_faturamento (12 meses fechados por mês do calendário); última venda = pedido mais recente não cancelado em sales_orders; última produção = última entrada de produto em stock_movements. Base, coloração, apoio e inativos ficam fora. Código em modules/producao/saude_estoque.rs. Decisões do Edson (2026-11-10): excesso acima de 2× o ideal, sem giro com 180 dias, primeira entrega só produtos acabados e kits'::text));
